## 4. Authentication & Authorization Implementation

### 4.1 JWT Token-Based Authentication

**Authentication Flow:**
```dart
class AuthService {
  final FlutterSecureStorage _storage;
  final ApiClient _apiClient;

  Future<AuthResult> login(String email, String password) async {
    final response = await _apiClient.post('/api/auth/login', 
      data: {'email': email, 'password': password});

    final tokens = AuthTokens.fromJson(response.data);
    await _storeTokens(tokens);

    return AuthResult.success(tokens.user);
  }

  Future<void> refreshToken() async {
    final refreshToken = await _storage.read(key: 'refresh_token');
    final response = await _apiClient.post('/api/auth/refresh',
      data: {'refresh_token': refreshToken});

    final tokens = AuthTokens.fromJson(response.data);
    await _storeTokens(tokens);
  }

  Future<void> _storeTokens(AuthTokens tokens) async {
    await _storage.write(key: 'access_token', value: tokens.accessToken);
    await _storage.write(key: 'refresh_token', value: tokens.refreshToken);
  }
}
```

### 4.2 OAuth 2.0 Integration

**Google OAuth Implementation:**
```dart
class GoogleAuthService {
  final GoogleSignIn _googleSignIn;

  Future<AuthResult> signInWithGoogle() async {
    final googleUser = await _googleSignIn.signIn();
    final googleAuth = await googleUser?.authentication;

    if (googleAuth \!= null) {
      final response = await _apiClient.post('/api/auth/google',
        data: {'id_token': googleAuth.idToken});

      final tokens = AuthTokens.fromJson(response.data);
      await _authService.storeTokens(tokens);

      return AuthResult.success(tokens.user);
    }

    return AuthResult.failure('Google sign-in failed');
  }
}
```

### 4.3 Role-Based Access Control

**Permission Management:**
```dart
enum UserRole { admin, manager, employee, viewer }

class PermissionService {
  final User _currentUser;

  bool canViewCustomers() => _currentUser.role \!= UserRole.viewer;
  bool canEditCustomers() => 
    _currentUser.role == UserRole.admin || 
    _currentUser.role == UserRole.manager;
  bool canDeleteCustomers() => _currentUser.role == UserRole.admin;
}
```

## 5. Responsive UI/UX Design Patterns

### 5.1 Breakpoint Strategy

**Responsive Breakpoints:**
```dart
class AppBreakpoints {
  static const double mobile = 600;
  static const double tablet = 900;
  static const double desktop = 1200;

  static ScreenType getScreenType(BuildContext context) {
    final width = MediaQuery.of(context).size.width;

    if (width >= desktop) return ScreenType.desktop;
    if (width >= tablet) return ScreenType.tablet;
    return ScreenType.mobile;
  }
}
```

### 5.2 Adaptive Navigation Patterns

**Multi-Platform Navigation:**
```dart
class AdaptiveNavigation extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return LayoutBuilder(
      builder: (context, constraints) {
        if (constraints.maxWidth < AppBreakpoints.tablet) {
          return MobileNavigation();
        } else {
          return DesktopNavigation();
        }
      },
    );
  }
}

class MobileNavigation extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text('SimpleCRM')),
      drawer: NavigationDrawer(),
      bottomNavigationBar: BottomNavigationBar(
        items: [
          BottomNavigationBarItem(icon: Icon(Icons.dashboard), label: 'Dashboard'),
          BottomNavigationBarItem(icon: Icon(Icons.people), label: 'Customers'),
          BottomNavigationBarItem(icon: Icon(Icons.shopping_cart), label: 'Orders'),
        ],
      ),
    );
  }
}
```

### 5.3 Responsive Layout Components

**Master-Detail Pattern:**
```dart
class ResponsiveCustomerView extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return LayoutBuilder(
      builder: (context, constraints) {
        if (constraints.maxWidth < AppBreakpoints.tablet) {
          return CustomerListView();
        } else {
          return Row(
            children: [
              Expanded(flex: 1, child: CustomerListView()),
              Expanded(flex: 2, child: CustomerDetailView()),
            ],
          );
        }
      },
    );
  }
}
```

